describe('ZIP Code Auto-formatting', () => {
  beforeEach(() => {
    cy.visit('/form');
  });

  it('should auto-format ZIP code as user types', () => {
    // Intercept the API call to prevent actual submission
    cy.intercept('POST', '/api/form/submit').as('formSubmit');

    // Get the ZIP code input field
    cy.get('[data-testid="zip-code-input"]').should('be.visible');

    // Type a partial ZIP code
    cy.get('[data-testid="zip-code-input"]').type('12346');

    // Verify the field is formatted with a hyphen
    cy.get('[data-testid="zip-code-input"]').should('have.value', '12345-');

    // Type the remaining part of the ZIP code
    cy.get('[data-testid="zip-code-input"]').type('6');

    // Verify the field is fully formatted
    cy.get('[data-testid="zip-code-input"]').should('have.value', '12345-6');

    // Submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Wait for the API call
    cy.wait('@formSubmit');

    // Verify success message appears
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Form submitted successfully');
  });

  it('should handle invalid ZIP code input and prevent submission', () => {
    // Intercept the API call
    cy.intercept('POST', '/api/form/submit').as('formSubmit');

    // Get the ZIP code input field
    cy.get('[data-testid="zip-code-input"]').should('be.visible');

    // Type an invalid ZIP code format
    cy.get('[data-testid="zip-code-input"]').type('123');

    // Verify the field is not formatted
    cy.get('[data-testid="zip-code-input"]').should('have.value', '123');

    // Attempt to submit the form
    cy.get('[data-testid="submit-button"]').click();

    // Verify validation error message appears
    cy.get('[data-testid="validation-error"]').should('be.visible');
    cy.get('[data-testid="validation-error"]').should('contain', 'Please enter a valid ZIP code');

    // Verify form was not submitted
    cy.get('[data-testid="form-container"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('not.exist');

    // Clear the input and verify error is cleared
    cy.get('[data-testid="zip-code-input"]').clear();
    cy.get('[data-testid="validation-error"]').should('not.exist');
  });
});
